 private LinearLayout row(LinearLayout parent){LinearLayout r=new LinearLayout(getContext());parent.addView(r);return r;}
 private TextView text(String s){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(13);v.setPadding(8,4,8,4);return v;}
 private Button button(LinearLayout parent,String label,String tag,Runnable action){Button b=new Button(getContext());b.setText(label);b.setTag(tag);b.setTextSize(12);b.setAllCaps(false);b.setMinWidth(0);b.setMinimumWidth(0);parent.addView(b,new LayoutParams(0,Math.round(48*getResources().getDisplayMetrics().density),1));b.setOnClickListener(v->{if(uiAllowed()&&b.isShown())action.run();});return b;}
 private EditText edit(LinearLayout parent,String hint,String tag,int limit){EditText e=new EditText(getContext());e.setTag(tag);e.setHint(hint);e.setTag(tag);e.setSingleLine(true);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(limit)});parent.addView(e,new LayoutParams(-1,-2));return e;}
 private Spinner spinner(LinearLayout parent,String tag,String[]labels){Spinner s=new Spinner(getContext());s.setTag(tag);ArrayAdapter<String>a=new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_item,labels);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);parent.addView(s,new LayoutParams(0,-2,1));return s;}
 private boolean uiAllowed(){return active&&isAttachedToWindow()&&isShown()&&hasWindowFocus()&&getWindowVisibility()==VISIBLE;}
 private void statusText(String s){if(status!=null)status.setText(s);}
 private void safe(Action a){try{a.run();}catch(Exception e){statusText(e.getMessage());}}
 private void show(int value){mode=value;views();}
 private void views(){if(reading==null)return;batch.setVisibility(mode==0?VISIBLE:GONE);packetScroll.setVisibility(mode==1?VISIBLE:GONE);history.setVisibility(mode==2?VISIBLE:GONE);reading.setVisibility(mode==3?VISIBLE:GONE);modes.setVisibility(mode==3?GONE:VISIBLE);actions.setVisibility(mode==3?GONE:VISIBLE);nav.setVisibility(mode==3?VISIBLE:GONE);status.setMaxLines(mode==3?1:2);}
 private void run(Work work,Done done){if(!uiAllowed())return;if(busy){statusText("前一项正在收尾，请稍后重试。");return;}final int token=++generation;busy=true;ack.setChecked(false);confirm.setEnabled(false);statusText("正在本机核对完整内容…");worker=new Thread(()->{JSONObject result=null;String error=null;try{result=work.run();}catch(Exception e){error=e.getMessage();}final JSONObject value=result;final String message=error;post(()->{worker=null;busy=false;if(token!=generation||!uiAllowed())return;if(message!=null){statusText(message);return;}safe(()->done.run(value));});},"f07-local-work");worker.start();}
 private void invalidatePreview(){generation++;if(worker!=null)worker.interrupt();pending=new JSONObject();pendingKind="";if(ack!=null)ack.setChecked(false);if(confirm!=null)confirm.setEnabled(false);}
 private JSONObject input()throws Exception{return object("question",question.getText().toString(),"riskProfile",new String[]{"balanced","conservative","aggressive"}[Math.max(0,risk.getSelectedItemPosition())],"maxCandidates",maximum.getSelectedItemPosition()+3);}
 private JSONArray selected(){JSONArray a=new JSONArray();for(int i=0;i<sourceList.getChildCount();i++){View v=sourceList.getChildAt(i);if(v instanceof CheckBox&&((CheckBox)v).isChecked())a.put(v.getTag().toString());}return a;}
 private void setReader(String full,String original){if(mode!=3)lastMode=mode;fullText=full;exportText=original;segment=0;renderReader();show(3);}
 private void renderReader(){int total=Math.max(1,(fullText.length()+47999)/48000);segment=Math.max(0,Math.min(segment,total-1));int a=segment*48000,b=Math.min(a+48000,fullText.length());if(a>0&&a<fullText.length()&&Character.isLowSurrogate(fullText.charAt(a)))a--;if(b>0&&b<fullText.length()&&Character.isLowSurrogate(fullText.charAt(b)))b--;reader.setText(fullText.substring(a,b));reading.scrollTo(0,0);position.setText((segment+1)+"/"+total+"段\n共"+fullText.length()+"字");previous.setEnabled(segment>0);next.setEnabled(segment+1<total);}
 void acceptBytes(byte[]bytes){if(!uiAllowed()||mode!=0)return;safe(()->{need(bytes.length<=8*1024*1024,"研究批次超过8MiB，未截断");String text=BusinessRestoreStore.utf8(bytes);invalidatePreview();raw.setText(text);show(0);persist();});}
 void previewBatch(){if(!uiAllowed()||mode!=0||busy)return;invalidatePreview();String text=raw.getText().toString(),at=Instant.now().toString();run(()->new ExternalResearchStore(file).preview(text,at),p->{JSONObject b=p.getJSONObject("displayBatch");setReader(ExternalResearchBatch.describe(b)+"\n\n来源核对\n"+p.getJSONArray("sourceChecks").toString(2)+"\n\n已有回执\n"+p.getJSONObject("previousReceipt").toString(2),b.getString("originalText"));if(p.getBoolean("replayed"))statusText(p.getBoolean("savedRowsIntact")&&p.getBoolean("receiptRowsMatch")?"此批次已有持久回执，未重复写入。":"此批次历史回执存在；当前原件/运行有删除或变化，未复活或覆盖。");else{pending=p;pendingKind="batch";statusText("已完整预览。勾选后，批次与研究运行在同一事务保存。");}persist();});}
 void refreshSources(){if(!uiAllowed()||mode!=1||busy)return;JSONArray keep=selected();run(()->object("materials",ResearchWorkbench.materials(new BusinessRestoreStore(file).capture())),r->{restoring=true;sourceList.removeAllViews();JSONArray ds=r.getJSONArray("materials");Set<String>ids=new HashSet<>();for(int i=0;i<keep.length();i++)ids.add(keep.getString(i));for(int i=0;i<ds.length();i++){JSONObject d=ds.getJSONObject(i);String id=KnowledgeAiHost.identity(d);CheckBox box=new CheckBox(getContext());box.setText(d.getJSONObject("row").getString("title")+" · "+id);box.setTag(id);box.setChecked(ids.contains(id));sourceList.addView(box);box.setOnCheckedChangeListener((b,value)->{if(!restoring)invalidatePreview();});}restoring=false;statusText("请明确勾选本次资料；目录不会全部自动选入。");setDarkTheme(dark);});}
 void previewPacket(){if(!uiAllowed()||mode!=1||busy)return;safe(()->{invalidatePreview();JSONObject ctx=context==null?new JSONObject():new JSONObject(context.read().toString()),in=input();JSONArray ids=selected();String q=query.getText().toString(),at=Instant.now().toString();run(()->ResearchWorkbench.packetPreview(file,in,ids,ctx,q,at),p->{pending=p;pendingKind="packet";setReader(ResearchWorkbench.packetReading(p),p.getJSONObject("run").getJSONObject("legacyOriginal").toString(2));statusText("已编排本机决策包，尚未调用AI。勾选后保存到原研究历史。");persist();});});}
 void confirmSave(){if(!uiAllowed()||mode==3||busy||pending.length()==0||!ack.isChecked()||!isShown()||!hasWindowFocus()||getWindowVisibility()!=VISIBLE)return;safe(()->{JSONObject held=new JSONObject(pending.toString());String kind=pendingKind;JSONObject ctx=kind.equals("packet")&&context!=null?new JSONObject(context.read().toString()):new JSONObject();run(()->kind.equals("batch")?new ExternalResearchStore(file).commit(held,true):ResearchWorkbench.savePacket(file,held,true,ctx),receipt->{pending=new JSONObject();pendingKind="";setReader(fullText+"\n\n真实本机提交回执\n"+receipt.toString(2),exportText);statusText("已保存并取得同库持久回执；可在保存历史及原研究历史回看。");persist();});});}
 void cancelPreview(){if(!uiAllowed()||mode==3)return;invalidatePreview();statusText("预览已取消，输入草稿保留；若已越过最终提交检查，提交仍可能完成，请核对历史回执。");safe(this::persist);}
 void reloadHistory(){if(!uiAllowed()||mode!=2||busy)return;invalidatePreview();run(()->{JSONArray batches=new ExternalResearchStore(file).history(),runs=new JSONArray(),rows=new BusinessRestoreStore(file).capture().getJSONObject("payload").getJSONArray("records");for(int i=0;i<rows.length();i++){JSONObject w=rows.getJSONObject(i);if(!"reports".equals(w.getString("kind")))continue;JSONObject r=BusinessRestore.row(w),run=r.optJSONObject("researchRun");if("ai_research_runs".equals(r.optString("legacySource"))&&run!=null&&"decision-packet".equals(run.optString("runType"))&&run.optString("id").startsWith("f07-packet-"))runs.put(ResearchRuns.stored(r));}return object("batches",batches,"runs",runs);},result->{historyRows=new JSONArray();historyAdapter.clear();JSONArray batches=result.getJSONArray("batches"),runs=result.getJSONArray("runs");for(int i=0;i<batches.length();i++){JSONObject h=batches.getJSONObject(i);historyAdapter.add(h.getJSONObject("row").getString("title")+(h.getBoolean("deliveryVerified")?" · 本机回执已核":h.getBoolean("historicalDeliveryRecorded")?" · 历史回执在，当前关联变化":" · 原回执缺失"));historyRows.put(object("kind","batch","value",h));}for(int i=0;i<runs.length();i++){JSONObject r=runs.getJSONObject(i);historyAdapter.add(r.getString("title")+" · 本机决策包");historyRows.put(object("kind","packet","value",r));}historyAdapter.notifyDataSetChanged();statusText("已重读本机历史；外部投递状态独立保留。");});}
 private void persist()throws Exception{if(restoring)return;marker=disk.save(object("schema","native-f07-draft/v1","raw",raw.getText().toString(),"question",question.getText().toString(),"query",query.getText().toString(),"risk",new String[]{"balanced","conservative","aggressive"}[Math.max(0,risk.getSelectedItemPosition())],"maximum",maximum.getSelectedItemPosition()+3,"sourceIds",selected(),"tab",mode,"segment",segment,"fullText",fullText,"exportText",exportText),marker);}
 private void restoreDraft()throws Exception{marker=disk.marker();if(marker.isEmpty())return;JSONObject s=disk.read(marker);restoring=true;raw.setText(s.getString("raw"));question.setText(s.getString("question"));query.setText(s.getString("query"));risk.setSelection(Math.max(0,Arrays.asList("balanced","conservative","aggressive").indexOf(s.getString("risk"))));maximum.setSelection(s.getInt("maximum")-3);mode=s.getInt("tab");lastMode=raw.getText().length()>0?0:1;fullText=s.getString("fullText");exportText=s.getString("exportText");segment=s.getInt("segment");sourceList.removeAllViews();JSONArray ids=s.getJSONArray("sourceIds");for(int i=0;i<ids.length();i++){String id=ids.getString(i);CheckBox box=new CheckBox(getContext());box.setText(id+" · 待重读核对");box.setTag(id);box.setChecked(true);sourceList.addView(box);box.setOnCheckedChangeListener((b,v)->{if(!restoring)invalidatePreview();});}restoring=false;invalidatePreview();renderReader();views();statusText("已恢复输入与完整阅读草稿；保存确认已清除，请重新预览当前来源。");}
 JSONObject saveState()throws Exception{persist();return object("schema","native-f07-marker/v1","sha256",marker);}
 void restoreState(JSONObject s){safe(()->{need("native-f07-marker/v1".equals(s.optString("schema"))&&disk.marker().equals(s.getString("sha256")),"F07短状态与私有草稿不符");restoreDraft();});}
 void fileStatus(String message){if(uiAllowed())statusText(message);}
 void setActive(boolean value){active=value;if(!value){invalidatePreview();safe(this::persist);}}
 void setDarkTheme(boolean value){dark=value;colors(this);}
 private void colors(View v){int ink=dark?0xffdae5f5:0xff1f3048;if(v instanceof LinearLayout||v instanceof ScrollView||v instanceof ListView)v.setBackgroundColor(dark?0xff101a27:0xffffffff);if(v instanceof TextView)((TextView)v).setTextColor(ink);if(v instanceof EditText)((EditText)v).setHintTextColor(dark?0xff9eb3cb:0xff65778b);if(v instanceof Button)v.setBackgroundTintList(ColorStateList.valueOf(dark?0xff26394f:0xffe9eef5));if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)colors(g.getChildAt(i));}}
 protected void onDetachedFromWindow(){active=false;invalidatePreview();safe(this::persist);super.onDetachedFromWindow();}
